  function getFilteredCharList() {
    const all = Object.values(currentState.关系);
    const pool = uiState.hideUnreached ? all.filter(function (c) { return c.unlocked || c.present; }) : all;
    const q = (uiState.charSearch || '').trim().toLowerCase();
    return pool.filter(function (c) {
      if (uiState.charFilter === 'present' && !c.present) return false;
      if (uiState.charFilter === 'unlocked' && !c.unlocked && !c.present) return false;
      if (uiState.charFilter === 'core' && !c.isCore) return false;
      if (uiState.charFilter === 'optional' && !c.isOptional && !c.isDynamic) return false;
      if (q) {
        const hay = (c.name + ' ' + c.关系类型 + ' ' + c.位置 + ' ' + c.lore.title + ' ' + c.lore.category + ' ' + c.lore.anchor).toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    }).sort(function (a, b) {
      if (a.present !== b.present) return a.present ? -1 : 1;
      if (a.unlocked !== b.unlocked) return a.unlocked ? -1 : 1;
      if (a.isCore !== b.isCore) return a.isCore ? -1 : 1;
      return b.好感 - a.好感;
    });
