stage":"S85","location":"幻城废墟深坑边缘、紫罗兰世界南方大陆小城","chars":["林恩","左左","艾维儿","入梦者"],"brief":"林恩误伤边缘醒转、点破鞭挞链后罢工宣言「我不奉陪了」、以「死吧」回敬要挟，织梦第一次失去对局面的掌控感，左左与林恩的羁绊完成一次深度确认。"},"E626":{"name":"自我了断与织梦屈服","stage":"S85","location":"紫罗兰世界南方大陆小城酒店房间","chars":["林恩","左左","艾雯爵士","艾维儿","入梦者"],"brief":"织梦亮舰队底牌劝降，林恩以自我了断相胁，织梦从「执鞭者」跌落为「跪规矩」的服从方，且因本质缺失实力受创，被污染者舰队被灵能指令引离深渊方向。"},"E627":{"name":"容器计划与三位一体历史","stage":"S85","location":"南方大陆小城酒店房间、紫罗兰世界上空回龙背","chars":["林恩","左左","欲望母树","艾维儿","入梦者"],"brief":"织梦交代历史修正论、超脱时间与莫比乌斯环，自承参与巨像智械创造，林恩获得外来者阵营的完整动机链与时间战争机制认知。"},"E628":{"name":"白烬训练与星寂拳法","stage":"S85","location":"冬泉谷、奇异世界时间小屋","chars":["林恩","左左","欲望母树","艾维儿","入梦者"],"brief":"织梦授白烬三形态、星寂共鸣增幅拳与守护之力三家本质，林恩获得三位一体运能体系，对堕落神灵级战力完成补课，守护之力、守护者家族与灭门恩怨补完外来者阵营史。"},"E629":{"name":"容器泄漏与神降前兆","stage":"S85","location":"奇异世界时间小屋与冬泉谷后山、冬泉谷","chars":["林恩","入梦者","真理神王","紫罗兰大君"],"brief":"织梦本质受创留有感知缺口、舰队强行拓路隐患未决，训练从「安稳窗口」转入「倒计时窗口」，林恩一方对风暴的逼近有了方向感而无时间表。"},"E630":{"name":"真理神王降临","stage":"S85","location":"紫罗兰世界冬泉谷法师塔下、后山三叉戟驻地","chars":["林恩","欲望母树","艾维儿","入梦者","真理神王"],"brief":"纱奈儿波动引七神锁定，真理神王金红纹路巨手携七神降临紫罗兰，织梦高维决斗掩护撤离，林恩决意遁逃保留斩首降临媒介之机。"},"E631":{"name":"七神阻击与星寂初战","stage":"S86","location":"紫罗兰世界残骸外的深空、破损旗舰周边空域","chars":["林恩","艾维儿","入梦者"],"brief":"七神分三神缠艾维儿、两神一魇围林恩、现实之神破屏障，林恩首战白烬加星寂，双杀力量之神与心灵之神，艾维儿陷入三神围攻。"},"E632":{"name":"白烬弑神与艾维儿解放","stage":"S86","location":"无序深空战场、殖装无序引擎的旗舰近域","chars":["林恩","艾维儿","未来画家"],"brief":"现实之神伪装舰队蝴蝶幻影被白烬弑杀，七神一魇全灭，破碎神界先遣利刃被连根拔起，「毁媒介放逐神王」的战术假设被遗言部分证伪。"},"E633":{"name":"最后一课与曲率逃生","stage":"S86","location":"混乱色彩洪流盘踞的战场、曲率空间乱流","chars":["林恩","艾雯爵士","艾维儿","入梦者","未来画家","真理神王"],"brief":"织梦战败甩出林恩、紫罗兰弹珠相赠，林恩成为七神歼灭战唯一的自由幸存者，「最后一课」完成入梦者一脉对渡鸦的传承闭环。"},"E634":{"name":"艾雯离队与深渊归返","stage":"S86","location":"破碎恒星小行星带、深渊曲率甬道、黑夜城","chars":["林恩","人偶夫人","倒吊天使","艾雯爵士","a01银色幻想","艾维儿"],"brief":"曲率归返深渊，双半神喜讯与大会正式公布织梦身份获欢呼，林恩对立夏的隐瞒与宣战，艾雯爵士独自离队「我在深渊等你。"},"E635":{"name":"未来林恩与梦境领域","stage":"S86","location":"黑夜城会议厅、林恩在黑夜城的房间、时间裂隙彼端","chars":["林恩","左左","猪头屠夫","黑弦月","羽毛笔","康斯坦丁"],"brief":"林恩向轮回神王求教梦境领域方向，三招之约领悟，林恩获得梦境领域，初诞者之力的运用从「操使工具」转向「展开自我」，为法则浪潮封印法与日后领域外放奠基。"},"E636":{"name":"远征军备与黑弦月参战","stage":"S86","location":"黑夜城外集结场、深渊第七位面外空间枢纽","chars":["林恩","人偶夫人","泰坦头颅","倒吊天使","黑弦月","a01银色幻想"],"brief":"黑弦月完成参战改造，远征军战力体系完整亮相，黑弦月以人偶之躯留在战场序列，林恩的「高墙」执念第一次对至亲的自主选择让步。"},"E637":{"name":"天鹰座首战与破碎之眼封印","stage":"S86","location":"现实宇宙天鹰座星区、破碎之眼外围无序地带","chars":["林恩","渡鸦","a01银色幻想","万机之神"],"brief":"远征首队突袭天鹰座最大破碎之眼，林恩初展梦境领域、金色边境引动主宇宙法则狂潮，一战封印破碎之眼，敌高位神灵驰援不及。"},"E638":{"name":"全宇宙闪电战","stage":"S87","location":"深渊第七位面空间枢纽、曲率通道","chars":["林恩","泰坦头颅","倒吊天使","a01银色幻想","康斯坦丁","入梦者"],"brief":"远征军连封多座破碎之眼，主宇宙百余座破碎之眼近半失守，被污染者大军成片失去指挥、陷入无组织动乱，破碎神界再建巢穴的成本急剧抬升。"},"E639":{"name":"伏击疑云与群星阳谋","stage":"S87","location":"深渊第七位面空间枢纽、曲率通道、现实宇宙天鹰座星区","chars":["林恩","倒吊天使","渡鸦","a01银色幻想","康斯坦丁","入梦者"],"brief":"自缚天使疑「太顺利」、推断敌方以杀渡鸦为名的阳谋，群星回路投射成远程战略工具，通讯中断虚惊后第二波突袭准备完成。"},"E640":{"name":"第二波突袭","stage":"S87","location":"现实宇宙天鹰座星区、主宇宙各边缘星区、深渊中枢","chars":["林恩","倒吊天使","康斯坦丁","入梦者","真理神王"],"brief":"第二波突袭多星区展开，敌方战略收缩、远征军获得主动权，真理神王的法则回声在远方愈发清晰，主宇宙大半星区光复，被污染者失去神界直接指挥。"},"E641":{"name":"深渊撤出决议","stage":"S87","location":"深渊第七位面、林恩星际堡垒、主宇宙新收复星区","chars":["林恩","人偶夫人","倒吊天使","a01银色幻想","康斯坦丁","入梦者"],"brief":"面对神王级威胁，林恩方权衡后定下撤出深渊的决议，留守与撤离的取舍摆上桌面，深渊命运悬于一线，深渊从主基地降格为弃子，奇异世界成为随身中枢。"},"E642":{"name":"信息泄露与三王警告","stage":"S87","location":"深渊第七位面星际堡垒、黑夜城高塔大殿","chars":["林恩","a01银色幻想","入梦者","未来画家"],"brief":"邋遢中年人携情报现身黑夜城高塔，揭双轨污染窃信机制，三王警告正确认泄露范围后给出两日界限，敌方幕后魇王弃魇保帅。"},"E643":{"name":"全军撤离与深渊陷落","stage":"S87","location":"黑夜城高塔大殿、深渊第一位面、第七位面空间中枢","chars":["林恩","倒吊天使","a01银色幻想","艾维儿","入梦者","真理神王"],"brief":"林恩方以最大规模空间召唤组织全军撤离、三六九等取舍，深渊作为经营已久的位面基地彻底易主，法则浪涛首次被敌方反向奴役。"},"E644":{"name":"罪火断后","stage":"S87","location":"深渊第一位面残空、迷雾之海入口外缘、三叉戟奇异世界内","chars":["林恩","泰坦头颅","倒吊天使","a01银色幻想","入梦者","真理神王"],"brief":"织梦抓肩吸噬林恩三位一体力量入二档绯红，燃烧生命召罪火化红焰长刀罪断后，军团失去织梦这位核心战力与导师，三位一体二档绯红与禁招罪首次现世并以教学的方式留给林恩。"},"E645":{"name":"巨像融合与白烬常态","stage":"S87","location":"三叉戟奇异世界殿堂、林恩体内精神世界与超维链接","chars":["林恩","左左","艾雯爵士","a01银色幻想","入梦者","以太"],"brief":"银幻坦白以太本质与迟发法则排斥、织梦「保险」碎片留言，林恩两次拒绝后巨像以死相逼，三位一体融合升华，白烬步入常态化。"},"E646":{"name":"迷雾海猎杀","stage":"S87","location":"迷雾之海全域、波动区域边缘、蒸腾迷雾深处","chars":["林恩","a01银色幻想","真理神王"],"brief":"林恩方于迷雾之海循环猎杀：钉杀、剥离神格、磨灭尸躯、折返双杀，减员十几含两中位神、大部队扑空，猎手与猎物的身份在迷雾中倒转。"},"E647":{"name":"真理神王改换策略","stage":"S88","location":"迷雾之海中央与各处搜捕区、幽冥海洪流段","chars":["林恩","左左","真理神王"],"brief":"金色少年判断林恩逼近神王位阶，弃用被海域扭曲的法则改用无序，捏爆腐化神灵召污染者献祭，追杀由搜索战转为以无序生灵扩张为核心的清场。"},"E648":{"name":"高塔引诱与二档罪火","stage":"S88","location":"迷雾之海出口与入口两侧的无序地带","chars":["林恩","左左","真理神王","紫罗兰大君"],"brief":"敌方献祭造出四大神嗣分路驻守扩大无序，迷雾之海的战场被四个无序生灵压缩为靠近幽冥海的一片，两位腐化上位神被重创。"},"E649":{"name":"真理神王一掌与傀儡疑云","stage":"S88","location":"迷雾之海入口一侧战场、幽冥海迷雾深处","chars":["林恩","左左","真理神王"],"brief":"林恩迎金手挥一拳折跃消失，神王发现力量在林恩身前一米被钳制、真理法则滞涩异常，疑其为傀儡下令收网，林恩与神王之间的实力差距被亲身量出。"},"E650":{"name":"诱敌深入与时间塌陷","stage":"S88","location":"幽冥海边境与下游洪流、幽冥海深处的奇异海域","chars":["林恩","左左","真理神王"],"brief":"林恩引敌入高塔所在时间尽头，撞涡流见塔下盘坐身影与棺椁，喊话后棺椁崩裂孤岛坍塌，半数腐化神灵被抛入各条长河或逐出时间线。"},"E651":{"name":"时间之外与左左冻结","stage":"S88","location":"时间之外的虚无、金色梦境领域内部、幽冥海孤岛","chars":["林恩","左左"],"brief":"林恩被抛出时间长河，借神王点拨在身前一米筑金色梦境修复己身但沉睡，林恩活了下来，但左左被永久冻结在时间之外，梦中呼唤的真相成为他日后必须面对的伤口。"},"E652":{"name":"时间尽头与唯一道路","stage":"S88","location":"幽冥海孤岛的时间壁垒、时间之外的虚无","chars":["林恩","左左","泰坦头颅","倒吊天使","艾雯爵士"],"brief":"林恩轰开时间壁垒寻左左，在雨孤岛听撑伞女孩陈述斩因果重铸过去的真相，林恩的阵营首次获得关于「未来的自己」「时间战争闭环」「林恩之名来历」的一方陈述。"},"E653":{"name":"金色领域与迷雾屠杀","stage":"S88","location":"幽冥海外围的物质洪流、迷雾之海残存区域、无序深空边缘","chars":["林恩","渡鸦","未来画家"],"brief":"林恩以金色浩日冒充神王诱敌，二档罪火幻梦领域定格上位神、压制无序焚尽幽冥海外围，迷雾之海一带的追杀力量基本瓦解。"},"E654":{"name":"深渊废墟与折翼天使","stage":"S88","location":"迷雾之海入口、深渊第一至第七位面","chars":["林恩","倒吊天使","入梦者","紫罗兰大君"],"brief":"林恩折返深渊逐位面目睹杀戮乐园，空间中枢葬场钉着放尽血的折翼天使，仍请陛下离去勿告姐妹，深渊已无一个原住民与守卫幸存的事实被林恩一方确认。"},"E655":{"name":"深渊残骸与主宇宙防线","stage":"S89","location":"深渊第七位面的空间机制、曲率乱流","chars":["林恩","入梦者","未来画家","真理神王"],"brief":"林恩入星空借织梦群星观测，发现数十星区再陷、破碎之眼接连摧星、第二道防线失守，林恩一方获得主宇宙最新战况。"},"E656":{"name":"边境因果封锁","stage":"S89","location":"主宇宙的边荒方向、曲率空间、一座破碎之眼附近的星空","chars":["林恩","羽毛笔"],"brief":"林恩折跃、航行、限制折跃连遭拦截偏离，越近边境意外越频，现象与因果神通吻合，推演敌方先锁死离境，最佳应对是屏蔽自身因果。"},"E657":{"name":"金色梦境屏蔽与重归起点","stage":"S89","location":"主宇宙边荒方向的虚空、深渊第一位面迷雾之海外","chars":["林恩","入梦者"],"brief":"林恩以梦境茧屏蔽因果，忽然感到过去某段因果被剪断眩晕间被拉回织梦大裂隙，林恩的逃亡链被因果裁剪整段收回，敌方的两大主使与大批腐化神灵、魇集结在深渊第一位面。"},"E658":{"name":"重归起点与背水一战","stage":"S89","location":"深渊第一位面迷雾之海外、织梦斩出的大裂隙旁","chars":["林恩","a01银色幻想","康斯坦丁"],"brief":"魇王下令围杀，林恩燃罪火迎战杀神灵与魇无数，魇王不下场仅消耗并挡住因果，林恩金矛与突围皆受阻，林恩一方看清魇不死不灭的本质与魇王的谨慎。"},"E659":{"name":"置之死地与极尽罪火","stage":"S89","location":"深渊第一位面迷雾之海外、织梦斩出的大裂隙旁","chars":["林恩","a01银色幻想","渡鸦","入梦者","紫罗兰大君"],"brief":"三轮漆黑矛雨将林恩钉穿跪倒，魇王走近欲炼化残魄，神格屏障挡住，林恩睁眼唤戟金梦困敌、四法则重塑身躯，魇王被极尽罪火重创、其存亡不明。"},"E660":{"name":"死前幻影与银色幻想救援","stage":"S89","location":"深渊第一位面塌陷后的余烬、主宇宙的法则洪流","chars":["林恩","小小","人偶夫人","泰坦头颅","倒吊天使","哭泣小丑"],"brief":"因果神王体内两意志相争被远方身影截断，魇王重聚不死，林恩法则崩断漂流被拉出洪流，魇王虽受重创仍活，因果神王在极限罪火与一个遥远身影面前停手。"},"E661":{"name":"封闭世界争夺","stage":"S89","location":"银色幻想开辟的封闭世界","chars":["林恩","小小","人偶夫人","泰坦头颅","倒吊天使","a01银色幻想"],"brief":"银色幻想斩退奇袭狱卒对峙集团，林蒙跪地要求交出林恩，银色幻想指控狱卒被渗透，封闭世界被强行撬动，数月独占的格局终结。"},"E662":{"name":"腐化刺杀与林恩苏醒","stage":"S89","location":"封闭世界","chars":["林恩","人偶夫人","倒吊天使","a01银色幻想","康斯坦丁","未来画家"],"brief":"混战中腐化者出手，银色幻想为林恩挡贯背利刃，至少两腐化根源破防、副官背刺被格，至少五名腐化狱卒与两名腐化根源尽数暴露，插翅难逃。"},"E663":{"name":"再见画家与七大神王格","stage":"S89","location":"画家的苍蓝世界","chars":["林恩","艾维儿","未来画家"],"brief":"画家点破治疗结果是她，托林恩带艾维儿去意志锚点，林恩明确了下一步路线，他获得万物神格，他对真理神王本尊产生了关键怀疑。"},"E664":{"name":"尘封相册与重归黑夜城","stage":"S89","location":"法师塔一楼与二楼卧室、苍蓝世界外、地狱黑雾之上","chars":["林恩","小小","人偶夫人","爱丽丝","泰坦头颅","巫神头颅"],"brief":"林恩在法师塔二楼翻见奈奈子相册与少女闺房，要画家交出空间神格无人应答，林恩对画家的门后少女闺房与相册初次正面冲击「盟友」框架。"},"E665":{"name":"漫天神格与空间神格","stage":"S90","location":"黑夜城林恩的寝室","chars":["林恩","未来画家","入梦者"],"brief":"林恩窥体内两股力量位置改变、隐约纠缠，林恩掌握了七大神王格星图这一追踪工具，空间神格之谜的答案第一次指向他自己，这将直接引出他对自身最大秘密的重新审视。"},"E666":{"name":"三重里世界与空间神格","stage":"S90","location":"林恩的寝室、系统空间内部","chars":["林恩","血肉支配者","未来画家","以太"],"brief":"林恩循共鸣寻至系统空间最深处，切开外壁踏入曲率乱流，反复实验证实坐标随请求瞬间转移，所谓私密空间一直在响应更高位的请求。"},"E667":{"name":"半神进阶与空间权柄","stage":"S90","location":"系统空间之外、曲率乱流深处的某处","chars":["林恩","未来画家","渡鸦"],"brief":"林恩循画卷找到空间神格，画家现身，抓取瞬间感知整个地狱系其上即松手，林恩确认系统空间是空间神格的投影、自己的「最大秘密」源自画家。"},"E668":{"name":"同生共死与远征分流","stage":"S90","location":"曲率乱流深处的神格之地、黑夜城全域","chars":["林恩","倒吊天使","a01银色幻想","康斯坦丁","未来画家"],"brief":"林恩抓取空间神格，画家敛去致密空间挤压他，临别交代一月时限，林恩在水晶棺椁里融合，画外浮现无序边疆被攻破。"},"E669":{"name":"银色幻想的告别与腐化疑云","stage":"S90","location":"黑夜城郊外荒原、三重里世界","chars":["林恩","人偶夫人","泰坦头颅","巫神头颅","a01银色幻想","康斯坦丁"],"brief":"泰坦挣脱不死诅咒踏半神走战神路，林恩悟空间真谛看清表层曲率三重界，黑夜城半神总数超过二十位且仍在增长，泰坦以战神序列跻身半神并锁定赴神界的意图。"},"E670":{"name":"出征前序与画家资源包","stage":"S90","location":"第四层、黑夜城中央广场、心海之上的木船","chars":["林恩","人偶夫人","渡鸦","a01银色幻想","康斯坦丁","未来画家"],"brief":"林恩升入第四层俯瞰主宇宙与地狱，悟破碎之眼为内外隧道、神界为主宇宙内核，银色幻想设原子矩阵监督，林恩看穿神界与主宇宙的真正结构关系，获得了神王级的空间权柄视角与机动性。"},"E671":{"name":"破碎神界与命运神国","stage":"S90","location":"黑夜城船头与北面黑海岸、地狱黑雾之上、黑夜城机械区","chars":["林恩","人偶夫人","渡鸦","哭泣小丑","a01银色幻想","艾泽法拉"],"brief":"康斯坦丁与人偶家互约、伊甸娜赴无序深渊，画家交代首要找时间神格、交付艾维儿龙蛋三具渡鸦，银色幻想成为需要被监督的疑似腐化者，万物神格的去向悬而未决。"},"E672":{"name":"龙卫庇护所与艾维儿孵化","stage":"S90","location":"荒原大裂隙崖壁内甬道、地下溶洞与中央水潭、龙卫庇护所","chars":["林恩","渡鸦","艾维儿"],"brief":"林恩潜入龙卫庇护所，音音入潭净化与龙蛋共鸣，龙蛋孵化为幼岁蓝龙称林恩为爹，林恩与艾维儿旧部接上头，龙蛋提前孵化为意识停留在一岁的幼龙。"},"E673":{"name":"时间神格的线索与庇护所效忠","stage":"S91","location":"龙卫庇护所溶洞与中央水潭、甬道深处","chars":["林恩","艾维儿","小小","未来画家"],"brief":"龙卫澜说明神界几近无活物、命运遗民失忆疑涉时间神格，林恩承诺去行宫取复苏，龙卫澜跪地效忠，林恩获得龙卫的名义效忠，但遗民并未效忠。"},"E674":{"name":"速度与静谧的旧神姐妹","stage":"S91","location":"龙卫庇护所、命运之城入口石碑、命运之城废墟街区","chars":["林恩","羽毛笔"],"brief":"神音默默作向导，法则纯度超半神与神灵关系密切，林恩一行掌握了神界当前的空档与魇军团潜伏的第一手情报，神音与默默成为向导，其来历疑点公开。"},"E675":{"name":"旧世神国的恐惧与因果化身","stage":"S91","location":"命运之城圣堂与地下神殿、壁画门后的旧世林地小世界","chars":["林恩","羽毛笔","艾维儿"],"brief":"小队降临神殿斩神取格，羽毛笔开门入隐藏旧林地，默默殉爆被时间倒退制止确认静谧，林恩取得衰败与火焰两枚神格，暴露风险因因果的察觉抬升。"},"E676":{"name":"银色太阳与因果清剿","stage":"S91","location":"旧世林地小世界内的遗民聚居地、隐蔽村庄","chars":["林恩"],"brief":"林恩走遍遗民区皆成火海，救村只余不足五分之一，老者指黑骑寻银色太阳，命运神国遗民几乎被清洗殆尽，银色太阳与时间神格的关联从传闻变为可追寻的位置。"},"E677":{"name":"因果化身的终止","stage":"S91","location":"旧世林地小世界内的遗民村庄、林地各处聚居地","chars":["林恩","时间王","紫罗兰大君"],"brief":"林恩身化千万改壁垒为牢笼转移遗民，废墟中银色太阳与因果化身交谈，因果与本体之弦被切断、三叉戟天外刺来，林地的敌方兵力被清空、遗民获救。"},"E678":{"name":"银色太阳引入时间之外","stage":"S91","location":"林地深处荆棘废墟、时间长河之外的黑暗虚空","chars":["林恩","时间王","紫罗兰大君"],"brief":"林恩抓破绽重归时间之外，林恩确认银色太阳是曾经的时间神王，获得时间之外的独处空间，时间神格的线索由此绑定在时间神王身上。"},"E679":{"name":"每一个轮回的陪伴","stage":"S91","location":"时间长河之外的黑暗虚空","chars":["林恩","轮回神王","时间王"],"brief":"时间神王展示轮回神王几乎每个轮回在林地等植灵苗苗长大从笑意到麻木，林恩悟旧世杀他的是命运非戒指，林恩看到轮回神王与苗苗跨越轮回的陪伴，旧世界败局的一条因果线被补上。"},"E680":{"name":"以永眠换解脱","stage":"S91","location":"几年前罪孽城之外的平台、时间长河之末的虚空","chars":["林恩","猪头屠夫","羽毛笔","轮回神王","时间王","紫罗兰大君"],"brief":"林恩带时间神王追溯罪孽城外，时间神王与轮回神王相认被拒，轮回自述灵魂控制之争为局、失败后大君与他同归于尽。"},"E681":{"name":"真正地结局与时间神王承诺","stage":"S91","location":"几年前罪孽城外定格的平台、时间长河之外","chars":["林恩","羽毛笔","轮回神王","时间王","紫罗兰大君"],"brief":"林恩悟永眠协议是大君以永恒换世界存续，试图带走羽毛笔被轰出时间长河，时间神王承诺助他找时间神格，林恩把当作真正的结局，理解轮回神王帮助他的复杂动机。"},"E682":{"name":"让我永远不会苏醒","stage":"S92","location":"林地废墟府邸上空、七彩乱流、命运神国地下神殿与地表","chars":["林恩","时间王","紫罗兰大君"],"brief":"银色太阳否认手笔、解释林地是大君为那女孩保留的承诺，林恩以空间神格把世界剥离炼化抛入混乱，回程下令庇护所撤离。"},"E683":{"name":"龙卫迁移与幼龙坐标","stage":"S92","location":"命运神国庇护所、三叉戟世界","chars":["林恩","艾维儿","左左","渡鸦","入梦者"],"brief":"林恩收庇护所入三叉戟世界跃迁艾维儿行宫外围、已成无序堡垒，幼龙被糖果与钥匙收买感应深处女主人之物，龙卫与遗民暂时安全地存放在三叉戟世界里。"},"E684":{"name":"艾维儿行宫潜入","stage":"S92","location":"艾维儿行宫外围与城墙","chars":["林恩","渡鸦","艾维儿","真理神王"],"brief":"渡鸦分身引爆声东击西，林恩潜入外围见上百半成品无序引擎的兵工厂，入立方体内干涉数十座引出主事者与十几位腐化智者。"},"E685":{"name":"又一个真理神王","stage":"S92","location":"艾维儿行宫第一二层的图书馆殿堂、行宫内部隐秘通路","chars":["林恩","入梦者","真理神王","时间王"],"brief":"图书馆金色身影自称真理理性碎片、本体被镇压在行宫深处，远征者只是窃格之魇，林恩获得织梦的下落、真理律令契约碎片、多枚腐化智者神灵的神格与行宫的完整结构情报。"},"E686":{"name":"神尸之路与七十二柱","stage":"S92","location":"艾维儿行宫第三层魇王殿、神尸水晶长廊、王座大厅","chars":["林恩","入梦者","时间王"],"brief":"林恩化乌鸦入第三层魇王殿，水晶长廊下是忠诚派神尸，王座后立通天柱，真理被时停定格，银色太阳称为不属于此时间线之物。"},"E687":{"name":"织梦还活着","stage":"S92","location":"艾维儿行宫第四层监狱、监狱最深处的织梦囚房","chars":["林恩","入梦者"],"brief":"二人入第四层镇守门魇，林恩点亮监狱烧杀污染者，监牢全是受折磨的狱卒龙卫神灵，林恩确认织梦还活着但近乎空壳，且被魇王的腐化力量渗透本源。"},"E688":{"name":"毁灭神格与兽王吞噬","stage":"S92","location":"艾维儿行宫第四层监狱最深处、行宫外的虚空","chars":["林恩","渡鸦","入梦者"],"brief":"真理诊断织梦被本源腐化、只能以初诞者之力推移，林恩送她入三叉戟世界，兽王投影吞渡鸦分身，织梦被暂时稳住，未来的救治悬而未决。"},"E689":{"name":"斩天一刀与兽王投影","stage":"S92","location":"神界第六层外走廊与废墟、第六层与第七层之间的虚空","chars":["林恩","真理神王","时间王"],"brief":"林恩以初诞者镇借神格位阶之魇，兽王吞格炼魇白骨铸甲，兽王被斩，毁灭神王格落到林恩手中，梦境领域与罪火长刀完成首次实战。"},"E690":{"name":"承诺与两不相欠","stage":"S92","location":"神界第六层外的虚空平台、第七层坍塌的边缘","chars":["林恩","真理神王","时间王"],"brief":"第七层光熄，补全归一的真理神王亲身现身、龙心在手，龙心回到林恩手中，成为开启神王国度的钥匙，真理以完整神王之身脱离林恩阵营与敌阵营，不受任何一方控制。"},"E691":{"name":"最终一舞与神界核心之门","stage":"S92","location":"神界边疆、第三层破碎宫殿与王座殿、第七层坍塌处","chars":["林恩","真理神王","渡鸦","未来画家"],"brief":"远征精锐归来，第三层真理坐回王座、七十二柱再破封，魇王因果金少年破门，真理拦下魇王，少年眉心神格归主，真理神王夺回神格并以金色屏障拦下魇王三人，站位明确不属任何阵营。"},"E692":{"name":"神王的国度与镜面的魇","stage":"S93","location":"神界最底层的神王国度","chars":["林恩","未来画家","时间王"],"brief":"林恩经龙心之门入神王界，银色太阳说明此地未被画家改造、魇为终焉之主一部分，林恩得知神界最底层是神格的孕育之地、神王们的旧国度。"},"E693":{"name":"镜面复刻与神王牢笼","stage":"S93","location":"神界最底层神王国度的金色法则风暴之中、远空梦魇集结线","chars":["林恩","渡鸦","时间王"],"brief":"镜魇压制林恩并开始复刻空间法则，蜂巢迷宫数十秒被破，林恩捏碎第二只渡鸦仍恢复不足半，镜魇第二眼睁开召上万梦魇。"},"E694":{"name":"漫天星火与神疆再临","stage":"S93","location":"神界最底层神王国度的金色法则风暴、远空星点区","chars":["林恩","渡鸦","时间王"],"brief":"林恩以梦境为根基与全法则建立联系、半数梦魇被引开，镜魇破浩日只见漆黑翎羽，魇王识破是死难渡鸦兄弟的灵魂光点神疆。"},"E695":{"name":"破绽与罪火绝杀","stage":"S93","location":"神界最底层神王国度的神疆之内","chars":["林恩","未来画家"],"brief":"林恩捕捉镜魇折跃需切法则与无序的破绽，混乱色彩化矛刺入眼眶，神疆锁链缚住并以法则洪流滋养混乱色彩，镜面之魇被斩，其残骸尚在。"},"E696":{"name":"追寻初诞者神格","stage":"S93","location":"神界最底层神王国度、艾维儿行宫第七层","chars":["林恩","未来画家","时间王"],"brief":"画家化身警告魇必复生、镜魔与兽王为三大主力之二，林恩独行遇金色昊阳即初诞者至高神格，请求被吞噬，林恩获知镜魔与兽王本体封印于时间之末、投影可复生、石柱是信标。"},"E697":{"name":"神王界决战与最后防线","stage":"S93","location":"神界最底层神王国度","chars":["林恩","渡鸦","未来画家"],"brief":"壁垒破碎三王率军团涌入，林恩吞噬本源有十分钟空档，扩空间为二道防线、召历代虚影人海战术，因果铁律抵达让梦魇必达。"},"E698":{"name":"给你十分钟","stage":"S93","location":"神界最底层神王国度","chars":["林恩","未来画家","渡鸦"],"brief":"画家现身一掌轰魇捏兽王骨爪，握断因果律法令反噬，魇王种三根终焉之柱三虚影，画家轰杀镜魔虚影消散，画家化身在十分钟里把魇王一方压回，随后力竭消散。"},"E699":{"name":"归来与反攻倒算","stage":"S93","location":"神界最底层神王国度、艾维儿行宫上空的大裂隙","chars":["林恩","艾维儿"],"brief":"终焉之柱被黄沙三叉戟抵住炸碎，魇王下令撤退，林恩缓步推进斩尽梦魇、钉杀魇王追杀兽王炼白骨，六十九柱被轰灭。"},"E700":{"name":"挥刀向过去与时间战争的开端","stage":"S93","location":"神界各处、主宇宙边疆的无序疆域、时间长河的裂缝","chars":["林恩","未来画家","渡鸦","入梦者","时间王"],"brief":"林恩重创因果，因果拒绝回头宣告时间战争开始，漆黑巨手与灾厄救走因果，林恩灌注本源切断注视，因果被时间之外的巨手救走，时间战争事实上开始。"},"E701":{"name":"我们失败了无数次","stage":"S93","location":"神界边疆","chars":["林恩","渡鸦","未来画家"],"brief":"画家承认故意把本源留神王界因果只有丈夫与渡鸦能用，她不全知、时间不连续、只为阻止祂全面苏醒，林恩确认画家把本源留在神王界是有意的安排，也确认自己是唯一契合者。"},"E702":{"name":"重归地狱","stage":"S93","location":"黑夜城广场、会议厅","chars":["林恩","人偶夫人","泰坦头颅","倒吊天使","康斯坦丁","孽主"],"brief":"林恩回归黑夜城家人跪迎，通报神界收复，点破本源是初诞者至高神格、画家又一次算计，对她提防加深，黑夜城确认神界收复与战争未止。"},"E703":{"name":"我们一起还","stage":"S93","location":"黑夜城会议厅、蜂巢、蜂巢现实","chars":["林恩","人偶夫人","泰坦头颅","倒吊天使","a01银色幻想","康斯坦丁"],"brief":"林恩下令两年后半神进驻破碎神界，军团转入破碎神界潜修轨道，为后续数年积淀铺路，银色幻想正式把自己的命运与林恩绑定，「我们一起还」成为二人关系的基调。"},"E704":{"name":"织梦与神格禁制","stage":"S94","location":"蜂巢现实、奇异世界浅水滩、奇异世界内的房间","chars":["林恩","a01银色幻想","入梦者","以太"],"brief":"林恩回应空间神格反噬——源头是三位一体，为创造神格编织罗网禁制并设权重权限，创造、空间两枚神王格的安全机制落地。"},"E705":{"name":"离别与以太吞噬","stage":"S94","location":"奇异世界织梦床榻边、碧蓝世界、出发前的某处","chars":["林恩","a01银色幻想","艾维儿","入梦者","未来画家","以太"],"brief":"林恩说明织梦伤势只能灵能续命，托付银色幻想护航，定性画家为无序三柱神之一将来或一战，织梦与艾维儿各有托付，林恩合法性孤身闭关的包袱卸下大半。"},"E706":{"name":"林蒙与未来","stage":"S94","location":"碧蓝世界、主宇宙边疆、天堂之战遗址","chars":["林恩","未来画家","紫罗兰大君"],"brief":"林蒙求原谅揭示狱卒分歧——很多人主动拥抱腐化、分不清灾厄是否就是大君，紫罗兰旧部的内部分裂公之于林恩，林恩对画家的复杂定性被林蒙亲手揭开。"},"E707":{"name":"数年过去与新神","stage":"S94","location":"黑夜城、神界各处、主宇宙边缘世界","chars":["林恩","人偶夫人","泰坦头颅","倒吊天使","a01银色幻想","欲望母树"],"brief":"数年过去：自缚天使登至高神位、人偶家成心灵之神、母树登自然神位，第四年神界颤动，魇以更多规模与四魇压境，黑夜城认清了与画家的断档级差距。"},"E708":{"name":"叛乱与毁灭神王格","stage":"S94","location":"黑夜城、神界各处、天堂之战遗址、时间长河的过去","chars":["林恩","a01银色幻想","欲望母树","康斯坦丁"],"brief":"首战后第十五天双地同时叛乱，船长护时间泡重创，师死亡之神判唯破而后立，林恩停不下回话，船长改为冲击毁灭神位，命运大变。"},"E709":{"name":"创造你的力量","stage":"S94","location":"时间长河的过去、轮回神王处","chars":["林恩","轮回神王","渡鸦","紫罗兰大君"],"brief":"林恩三年无数次切磋仍被一掌拍出，轮回神王连环追问身体灵魂意志，林恩顿悟只有意志才是真正的自己，林恩获得的身份定位与的方法学钥匙。"},"E710":{"name":"更高的境界","stage":"S94","location":"时间长河的过去、天堂之战遗址苍白耀阳","chars":["林恩","轮回神王","紫罗兰大君"],"brief":"林恩悟梦境映照是第一门槛、意志即力量更深，尝试映照发现唯法则之线能刹那成真，想创造必须先了解，林恩获得的初悟与方法学。"},"E711":{"name":"机械狂潮","stage":"S94","location":"主宇宙边境各星区、神界内环、黑夜城上空","chars":["林恩","a01银色幻想","康斯坦丁","未来画家","轮回神王"],"brief":"第五年二次战争规模数十倍，画家下场以一敌四全杀四魇，梦魇消耗战略升级，主宇宙的秩序在梦魇消耗战中几乎崩塌，幸得银色幻想逆转。"},"E712":{"name":"积淀与出不去的轮回王","stage":"S94","location":"神界黑夜城、天堂之战遗址、时间长河的过去","chars":["林恩","a01银色幻想","轮回神王","时间王","以太"],"brief":"第六年林恩以太熔铸纳米机械化、能长期稳于罪火，与时间神王对招仍差一点——逻辑所困，林恩真正能常态维持罪火，三位一体稳态迈出。"},"E713":{"name":"十年战争","stage":"S94","location":"时间长河的过去、主宇宙外环最后一颗星球北极点","chars":["林恩","人偶夫人","倒吊天使","a01银色幻想","欲望母树","艾维儿"],"brief":"林恩停在十三年前感悟竟百年，十年后魇潮反扑魔增至六神王级，艾维儿第十一年复苏，边境大半失守，林恩得到「历史重塑」的警告并被许诺「剧变将至」的命运节点。"},"E714":{"name":"暴风雨前的宁静与灾厄降临","stage":"S94","location":"人偶家所在的心灵之海、外环前线、黑夜城中央大殿","chars":["人偶夫人","倒吊天使","a01银色幻想","欲望母树","艾维儿","未来画家"],"brief":"人偶家被梦魇反向突破被狂风救回，三、四次战争连败后魇潮突撤，地狱四王降临面对画家，主宇宙从「魇潮战争」跃迁至「直面灾厄」的层级。"},"E715":{"name":"全面战争","stage":"S94","location":"神界、黑夜城、破碎神界、主宇宙边境、天堂之战遗址","chars":["林恩","倒吊天使","艾维儿","未来画家","轮回神王"],"brief":"灾厄复苏吞噬群星，大坠落记忆席卷，地狱四王说出权重论——主宇宙湮灭即终焉之主诞生，画家与灾厄再度对决的宿命已下场。"},"E716":{"name":"神疆献祭与红魔幻想","stage":"S94","location":"主宇宙内环、破碎神界、天堂之战遗址、神界中央广场废墟","chars":["林恩","倒吊天使","a01银色幻想","艾维儿","康斯坦丁","轮回神王"],"brief":"七柱魇压境，主母下令神疆献祭——亿万万生灵燃金火把银幻与船长推上一念神王之位，林恩收刀十年罪火，神疆以亿万柴薪燃起的最后底牌「一念神王」虽成，但仍然不够。"},"E717":{"name":"选择与背叛，他回来了","stage":"S94","location":"神界黑夜城镜面大裂隙、神界外围","chars":["林恩","倒吊天使","a01银色幻想","康斯坦丁"],"brief":"银幻断神疆链接自告带魇王去第四层同往作证，四魇随她动身，四魇魔被困于第四层，银色幻想以命相搏、即将死于黑蛇噬魂时迎来「那一刀」，林恩正式归来。"},"E718":{"name":"回归与钉住神疆","stage":"S94","location":"主宇宙核心空间的第四层、神界黑夜城、主宇宙中央星域","chars":["林恩","a01银色幻想","艾维儿","康斯坦丁"],"brief":"林恩在第四层救银幻焚尽魇王，宣三位一体之力本就外来者之力会一点偿还，林恩已正式归来，「三对一优势在你们」的豪言已出。"},"E719":{"name":"恐怖成长与灾厄边境决战","stage":"S95","location":"主宇宙前线、内环星区、灾厄边境","chars":["林恩","艾维儿","渡鸦","未来画家","紫罗兰大君"],"brief":"林恩以稳定罪火与刀鞘接下镜魔、兽王、人首蛇身魇三魇围攻，把战场引向边疆逐一点破防御迫退三魇，艾维儿协办敌情。"},"E720":{"name":"守约与边境汇合","stage":"S95","location":"灾厄边境、无序黑潮、画家秩序战场","chars":["林恩","未来画家"],"brief":"林恩穿黑潮汇合画家，她以蓝色秩序形态独抗灾厄本体、形体持续缩小仍守约把灾厄挡在主宇宙外，林恩确认画家正在以自身拖延灾厄，历史梦魇层成为下一条调查线索。"},"E721":{"name":"灾厄梦魇层推进","stage":"S95","location":"灾厄内部、历史梦魇层、蓝色秩序通道","chars":["林恩","未来画家","渡鸦"],"brief":"林恩随从画家入灾厄内部，黑潮不断生成历史强者扭曲残影，击碎后于远处重聚，林恩知晓初诞者在沉睡中维系大梦与渡鸦死难真相，直面画家以身饲虎的最终方案。"},"E722":{"name":"秩序裂隙与梦魇围攻","stage":"S95","location":"灾厄内部、历史梦魇层、蓝色秩序边界","chars":["林恩","未来画家","渡鸦","艾维儿"],"brief":"林恩与画家沿蓝色秩序通道继续推进，黑潮从外侧反复挤压，画家多次冲向边界、形体不断缩小坚守缝隙，画家力量继续消耗，林恩获得向最深黑暗推进的短暂路线。"},"E723":{"name":"向最黑暗拓路","stage":"S95","location":"灾厄黑瞳深处、无尽黑墙、渡鸦星炬通道","chars":["林恩","渡鸦","未来画家"],"brief":"画家牺牲拖延终焉苏醒，林恩背着画家成功突破外层黑墙，直面灾厄大梦深处的旧日神王幻影与大君残影，拔刀向最黑暗拓路、渡鸦尸骸与三叉戟齐鸣引开黑瞳、冲破黑墙直面旧日黑影成立。"},"E724":{"name":"只能靠我们了","stage":"S95","location":"灾厄核心无尽幻梦长路、破碎黑夜城、神界废土地狱王旗","chars":["林恩","左左","a01银色幻想","艾维儿","康斯坦丁","未来画家"],"brief":"林恩返回破碎黑夜城，艾维儿蓝色本源亮起、继承部分紫罗兰权柄并接管地狱、狱卒与残存神界，银幻、船长仍沉睡，画家献祭换取主宇宙和平休整期，狱卒与黑夜城融合为统一指挥体系。"},"E725":{"name":"对不起左左与时间神格","stage":"S95","location":"时间之外、黑夜城残区、古老时间神国","chars":["林恩","左左","小小","倒吊天使","康斯坦丁"],"brief":"林恩沿时间太阳线索探望被时间冰封的左左，架桥屡被时间流撕开，时间太阳说明唯有取得完整时间神格才能救回她，左左在时间之外得到安全锚定。"},"E726":{"name":"尽头与漫长寒冬","stage":"S95","location":"过去时间节点的轮回神王溪畔、无序深空战场","chars":["林恩","倒吊天使","渡鸦","轮回神王"],"brief":"重建数年间噩梦规模持续增长，林恩可击杀二十级噩梦却陷入梦境瓶颈，罪火与力量难以自然进阶，直筒主干线仍胜过原地死守。"},"E727":{"name":"不能再等下去了","stage":"S95","location":"黑夜城王庭大厅、无序深空前线、王座闭关禁制区","chars":["林恩","倒吊天使","入梦者"],"brief":"林恩沿黑狱门槛探入意识，看到由无法归还的灵魂、罪火与梦境残片构成的深层结构与三位一体残留路径，身体现黑火重塑征兆。"},"E728":{"name":"织梦醒来与无法开口的真相","stage":"S95","location":"奇异世界织梦居所、三叉戟浩日锚定区、织梦闺房结界内外","chars":["林恩","入梦者","未来画家"],"brief":"织梦自沉睡苏醒，灵能源头腐蚀不可修复，断续说出三阶形态需以信仰、灵魂与因果为燃，织梦掌握了开启三阶形态黑狱的真正钥匙，但为了不让林恩知晓必死结局、也为了帮他跨过唯一性门槛。"},"E729":{"name":"战争永无止尽","stage":"S95","location":"奇异世界织梦血泊闺房、神疆外围罪火防线","chars":["林恩","艾雯爵士","a01银色幻想","康斯坦丁","入梦者"],"brief":"二十余高阶噩梦迫近，终焉柱自星区废墟重长，把灾厄注视引向神疆，林恩退出黑狱门槛应战，发现敌在拖延等待灾厄转向。"},"E730":{"name":"送葬的黑雨与艾雯爵士","stage":"S95","location":"边疆沦陷工业星球港口、古老魔法文明破碎王都","chars":["林恩","艾雯爵士","入梦者"],"brief":"自我放逐二十余年的艾雯爵士终于迎来了他的创造者织梦，一场关于「罪火」真相与「骗子」宿命的临终托付即将展开。"},"E731":{"name":"罪恶王座","stage":"S95","location":"边疆废墟风雨处、黑夜城王庭殿堂、奇异世界织梦空房","chars":["林恩","艾雯爵士","入梦者"],"brief":"林恩于黑夜城王庭接触罪恶王座，前线死者、信仰残响与灾厄黑火汇聚，艾雯告诉织梦已死、三阶形态后续仍会卷入更多灵魂。"},"E732":{"name":"成熟就意味着失去","stage":"S96","location":"黑夜城王庭、罪恶王座、信仰残响区","chars":["林恩","艾雯爵士","入梦者"],"brief":"林恩从王座听见亿万带着痛苦与等待的疑问，确认织梦之死不可逆转，林恩开始把个人失去转化为建立信仰帝国的责任，艾雯成为终局秘密的承载者。"},"E733":{"name":"三阶形态的黑火","stage":"S95","location":"黑夜城高墙风雪处","chars":["林恩","艾雯爵士","入梦者"],"brief":"艾雯说明黑狱之火须以众生亲自参与的信仰为柴薪才能稳定燃烧，最终跃迁将让林恩付出生命并卷入相连灵魂，林恩知晓了自己踏入三阶形态必死的结局。"},"E734":{"name":"你将成为一个骗子","stage":"S96","location":"黑夜城信仰厅、主宇宙星域通讯网、艾雯议事处","chars":["林恩","艾雯爵士","倒吊天使","入梦者","未来画家"],"brief":"艾雯接受骗子职责，把林恩将死与众生燃烧真相压入只有自己能开的记忆层，信仰帝国完成制度雏形，林恩登临王座的条件被建立。"},"E735":{"name":"登临王座","stage":"S96","location":"罪恶王座、黑夜城中央王庭、主宇宙信仰网络","chars":["林恩","艾雯爵士","左左","倒吊天使","渡鸦"],"brief":"林恩登临罪恶王座，亿万信仰与怀疑、恐惧齐涌入其意识，林恩成为信仰帝国中心，三十只噩梦的入侵将检验黑火，林恩登临王座、信仰网络运转、三类星域制度与黑火供能成立。"},"E736":{"name":"战端再起与巅峰见证","stage":"S96","location":"三大圣堂至高王座、旧日幽冥海后门通道","chars":["林恩","艾雯爵士","倒吊天使"],"brief":"三十只噩梦同时冲击，神疆撕裂、信仰殿接连断裂，王座信仰被敌消耗，林恩屏障愈薄，林恩在力量最低谷迎来了有史以来最凶险的三十魇魔围杀。"},"E737":{"name":"信仰退潮与一点黑火","stage":"S96","location":"神界黑夜城前空大梦战场、三大圣堂信仰中枢","chars":["林恩","倒吊天使","艾雯爵士"],"brief":"噩梦逼入退潮，强行崇拜使信仰变薄，避难区一孩子坚持相信明天、带人修复节点，王座首次收到清晰个人信念，虚假的盲从之神死于退潮，真正的众生之王在绝境中诞生。"},"E738":{"name":"碾压与未来希望","stage":"S96","location":"彻底崩解的神界星空、黑夜城重逢广场","chars":["林恩","小小","倒吊天使","艾雯爵士","a01银色幻想","欲望母树"],"brief":"一点黑火沿信仰网络反向蔓延，三十噩护层依次崩裂被本源锁定压下，战后黑火未熄、把剩余信仰送回各节点供修复，三阶形态黑火首战告捷，全宇宙信仰攀上巅峰。"},"E739":{"name":"还能再烧什么呢","stage":"S96","location":"破碎神界废墟、三大圣堂王座大厅","chars":["林恩","倒吊天使","艾雯爵士"],"brief":"黑火吞尽剩余信仰、王座火焰转稀薄，三十噩残骸仍向终焉传讯，帝国决策中心正式收缩至三大圣堂核心圈，而为了解决黑火燃料与众生信仰的因果连接极限。"},"E740":{"name":"他已拜托过我与命运轨迹","stage":"S96","location":"三大圣堂巨门外长廊、被放逐的命运国度溪畔岩石","chars":["林恩","倒吊天使","艾雯爵士","羽毛笔","轮回神王"],"brief":"艾雯带王座委托抵命运之地，请羽毛笔把每名参与信仰者沿因果与林恩连接，地狱失却三分钟的草蛇灰线正式回收，获得准神王位格与自由意志的羽毛笔即将带着自己的选择飞向三大圣堂。"},"E741":{"name":"你我皆凡人与梦幻泡影","stage":"S96","location":"边缘工业星球、林恩金像广场、修院与星空航道","chars":["林恩","羽毛笔"],"brief":"羽毛笔入凡人城市亲眼见互救、修路与守护陌生人，把参与者依次接入命运网络，凡人盛景在终焉威胁下的脆弱性彻底暴露，羽毛笔在悲恸中下定决心返回黑夜城与艾雯完成最终命运之网。"},"E742":{"name":"终焉之火与完美世界","stage":"S96","location":"主宇宙边疆战场、黑夜城圣堂、时间长河之外的虚空","chars":["林恩","艾雯爵士","羽毛笔","轮回神王"],"brief":"羽毛笔把凡人因果接王座，黑火向终焉之火转化，信仰帝国步入战争减少、城市修复的黄金时代，王座覆一层完美世界光幕。"},"E743":{"name":"归来的小丑与最后辉煌时代","stage":"S96","location":"黑夜城王庭、黑夜城城墙、主宇宙无序边境","chars":["林恩","哭泣小丑","艾雯爵士","a01银色幻想","康斯坦丁"],"brief":"小丑携八音盒自无序深空归来，报无序生物持续自我拆解、众多个体记忆与名字将被抹去，乐者残响指向终焉之火深处。"},"E744":{"name":"苏醒的信号","stage":"S96","location":"遥远时光节点、阿鼻地狱狱卒集结地、黑夜城王庭","chars":["林恩","哭泣小丑","艾雯爵士","艾维儿","轮回神王"],"brief":"王座黑色裂纹扩大、所有无序生物同时停动，终焉苏醒信号自时间外传来，艾雯向林恩承认最怕的是他在所有人消散后独自留下。"},"E745":{"name":"我怕你孤单啊与最后晋升","stage":"S97","location":"罪恶王座、黑夜城王庭、信仰帝国核心","chars":["林恩","倒吊天使","艾雯爵士","羽毛笔"],"brief":"艾雯向母亲摊开最终晋升的真实代价——林恩将燃于火、相连灵魂俱被卷入，最终牺牲正式启动，黑夜城即将面对七十一噩梦的全面进攻。"},"E746":{"name":"我们绝不懊悔","stage":"S97","location":"黑夜城城头与木船、城外墓园、爱丽丝幸福之家、人偶庄园","chars":["林恩","小小","人偶夫人","倒吊天使","黑弦月","艾雯爵士"],"brief":"黑夜城各防区完成最后部署，主母把防守顺序交银幻与船长、人偶家重连断点，普通信徒把晶源与物资送往医院与避难区。"},"E747":{"name":"最终黑暗","stage":"S97","location":"主宇宙黑火边境防线、黑夜城空荡王宫与王庭议事厅","chars":["林恩","倒吊天使","a01银色幻想","艾维儿","康斯坦丁"],"brief":"七十一噩柱同时落下，外环内环神界边疆同被击穿，金色神疆断裂，最终黑暗全面降临主宇宙，前线陷入惨烈消耗战，主母留守黑夜城准备迎接最后的宿命。"},"E748":{"name":"对不起林恩我骗了你","stage":"S97","location":"三大圣堂、主宇宙三道边疆防线、古老命运之境","chars":["林恩","艾雯爵士","羽毛笔","轮回神王"],"brief":"艾雯向林恩承认此前隐瞒的并非单纯死亡、而是所有相连灵魂俱会被黑火抽取，罪恶王座的献祭本质彻底揭开，主宇宙亿万生灵与黑夜城亲友的因果线进入全面燃烧阶段。"},"E749":{"name":"因果燃烧与最后亲缘","stage":"S97","location":"命运因果网络、三大圣堂、黑夜城及主宇宙各星域防线","chars":["林恩","艾雯爵士","羽毛笔"],"brief":"因果网络把与林恩相连的灵魂依次抽离转为王座黑火，名字与记忆一截截断开，林恩与主宇宙的因果牵绊被大幅烧融转化为终焉之火燃料，黑夜城本体成为全宇宙最后的信仰之城与决战中心。"},"E750":{"name":"最后的信仰之城","stage":"S97","location":"黑夜城、爱丽丝幸福之家、黑夜城上空折跃通道","chars":["林恩","爱丽丝","泰坦头颅","巫神头颅","倒吊天使","喵喵"],"brief":"最后信仰之城把残存信徒、医院与军团聚于内环，女巫神以自身神性硬挡黑潮、泰坦以战神之力稳城门，王座自城中信仰续燃。"},"E751":{"name":"无法退却的牺牲","stage":"S97","location":"黑夜城外虚空第一道防线、黑夜城城头前线","chars":["小小","泰坦头颅","巫神头颅","哭泣小丑","a01银色幻想","康斯坦丁"],"brief":"女巫神把神性展成覆城门的屏障层层剥落、泰坦把怒火化作一次穿噩冲击，小丑携八音盒自另一侧赶到，撕开一噩制造撤离空白。"},"E752":{"name":"最后的乐章","stage":"S97","location":"黑夜城外虚空战场、神疆覆盖边缘、黑夜城与阿鼻地狱废墟","chars":["林恩","人偶夫人","泰坦头颅","哭泣小丑","艾维儿","康斯坦丁"],"brief":"小丑把八音盒旋律压入无序残片令一噩外壳错位，泰坦集怒火穿其本源击碎，城墙黑潮暂被推回、撤离航道打开，哭泣小丑与泰坦壮烈战死并拉一尊七十二柱魇魔与三分之一梦魇集群陪葬。"},"E753":{"name":"船长与人偶家","stage":"S97","location":"黑夜城城门缺口与内城墙、爱丽丝幸福之家","chars":["人偶夫人","a01银色幻想","康斯坦丁","孽主","夏娃"],"brief":"船长携毁灭神格守黑夜城内城入口、人偶家以丝线铺入城墙墓船与军团节点，船长灵魂泯灭化为人偶家丝线牵引的最后战偶，幸福之家妇孺开始转移，黑夜城内城墙迎来沦陷前的最终决战。"},"E754":{"name":"黑夜城沦陷","stage":"S97","location":"黑夜城王庭、内城废墟、最后撤离防线","chars":["林恩","倒吊天使","a01银色幻想","艾维儿"],"brief":"噩潮越过内城，王庭、医院、信仰殿、旧居所同毁，银幻逐一炸断退路传送门，主母取下断墙上旧旗，黑夜城从家园与据点变成因果记忆，主要角色被迫转入终局防线。"},"E755":{"name":"最后的绽放","stage":"S97","location":"黑夜城王庭阶梯、三大圣堂黑火结界内","chars":["林恩","倒吊天使","a01银色幻想"],"brief":"银幻承主母亲授的三叉戟于废墟展开最后机械防线，主母把自身神性与王庭石柱接上光幕正抗黑潮，主母以全部天使本源的最后绽放守住王庭正门。"},"E756":{"name":"你也并不孤单啊","stage":"S97","location":"黑夜城王庭高耸石柱、王庭废墟战场、黑夜城外围深渊裂口","chars":["林恩","倒吊天使","黑弦月","a01银色幻想","艾维儿","孽主"],"brief":"旧日天使、军团与残存守卫者自撤离点返身回废墟，把残缺法则重新接入王庭，主母、孽主、艾维儿及守望者军团与黑夜城老兵全员壮烈殉城。"},"E757":{"name":"梦中的弦奏与现实悲歌","stage":"S97","location":"罪恶王座深层梦境、圣所最后一道守护结界内外","chars":["林恩","小小","人偶夫人","黑弦月","羽毛笔","入梦者"],"brief":"王座黑火把黑夜城废墟的呼喊与告别拉成梦中弦奏，人偶小姐承人偶家残余以丝线反复编织最后墙面，黑弦月作为黑夜城最后一名守城神明战死于圣所结界外，林恩带着满腔悲痛冲入废墟。"},"E758":{"name":"小小与末日之下","stage":"S97","location":"黑夜城废墟、圣所最后一道守护结界与黑夜城残垣","chars":["林恩","小小","艾维儿"],"brief":"林恩沿因果线在废墟中找到被末日法则压石下的小小，黑火只能燃烧转化无法复生，小小的死亡击穿林恩最后的心理支点，黑火将转而吞噬无序与噩梦。"},"E759":{"name":"五十九噩梦与灾厄退却","stage":"S97","location":"命运之境、黑夜城废墟与无序深空战场、黑夜城外墓园","chars":["林恩","小小","人偶夫人","艾雯爵士","羽毛笔","康斯坦丁"],"brief":"小小之死让林恩意识越过边界，王座黑火转向无序残骸与末日废墟，七十二柱魇魔被林恩一举屠灭五十九尊，灾厄退回无序深渊沉眠，织梦最后的灵魂火苗由苗苗保存。"},"E760":{"name":"敬明天","stage":"S98","location":"残存宇宙、幸存者聚居点、废墟星球","chars":["林恩","艾雯爵士","未来画家"],"brief":"林恩沿残余星光寻得约两千幸存者，修居所、配食、名录一切皆尽力，法则衰退仍带走绝大多数直至只剩一人，林恩确认自己成为唯一活动者，重建与时间外行动成为新的长期路线。"},"E761":{"name":"挡在那岁月长河","stage":"S98","location":"残存宇宙、重建黑夜城、时间之外","chars":["林恩","羽毛笔","轮回神王"],"brief":"林恩用幸存者记忆重建黑夜城轮廓，亲手固定城墙、王庭、墓地与传送节点，冲击时间外壁屡被攻击折返，林恩在时间之外与轮回神王爆发宿命对决，即将迎来两人昔日“三招之约”的最终清算。"},"E762":{"name":"你出师了林恩","stage":"S98","location":"时间之外、岁月长河外缘","chars":["林恩","轮回神王","艾雯爵士"],"brief":"轮回神王切断与部分过去的联系、把被切下因果燃进黑火，长河外壁裂出短暂缝隙，遗力与「你出师了」之语交林恩后全燃。"},"E763":{"name":"第二个门槛","stage":"S98","location":"时间之外、重建黑夜城、主宇宙无序边界","chars":["林恩","羽毛笔","轮回神王"],"brief":"无尽沉眠带林恩入一座不断变换的黑夜城，轮回神王燃下的因果火于梦底聚成第二门槛，门槛前无序、秩序、终焉残片交错。"},"E764":{"name":"无序的大梦","stage":"S98","location":"主宇宙无序边界、时间之外","chars":["林恩","羽毛笔","轮回神王"],"brief":"无序大梦把黑夜城拆成无数碎片，林恩于其中失去方向，羽毛笔于时间之外以命运线固定林恩与重建黑夜城的因果，防碎片全散。"},"E765":{"name":"无法遏制的衰退与终于等到你","stage":"S98","location":"时间之外、林恩的无序—秩序轮转大梦","chars":["林恩","左左","羽毛笔"],"brief":"羽毛笔笔身开裂、于冻结时间碎片中找到左左，把她拖向未来入口，林恩成功迈过第二门槛在秩序梦境中点燃黑火，左左被完好护下，而化为凡人老妇的羽毛笔即将迎来最后的告别。"},"E766":{"name":"我们一定会重逢的","stage":"S98","location":"时间之外、林恩的金色秩序大梦外缘","chars":["林恩","左左","羽毛笔"],"brief":"衰老化凡的羽毛笔将左左交托林恩，婉拒转化梦境眷属以免阻碍他燃尽梦境，拥抱立下之约，并将在回光返照的最后时光里进入林恩化作伊甸园的梦境完成最后的告别。"},"E767":{"name":"左左与仿佛如初","stage":"S98","location":"林恩的伊甸园梦境、时间之外、重建黑夜城","chars":["林恩","左左","羽毛笔"],"brief":"羽毛笔回光返照入伊甸园梦境与狸猫林恩追逐消散，左左苏醒随林恩回黑夜城立碑、化作左手并喷农药烤肉重获眼泪，林恩走出了孤王死寂，与左左重新结为生死共犯，在黑夜城潜心转化黑火。"},"E768":{"name":"时间战争的开端","stage":"S98","location":"重建黑夜城、时间长河、地狱中心大山地下棺椁","chars":["林恩","左左","渡鸦"],"brief":"林恩左左沿时间长河入早期节点寻终焉、渡鸦、旧日因果最初交汇处，黑火只能留有限规模，林恩正式作为“未来的白发身影”参战时间战争，即将面对时间裂隙对面魇王提出的“百年之约”诱惑。"},"E769":{"name":"如果可以给你选择","stage":"S98","location":"过去圣堂大门前、紫黑色时间裂隙外","chars":["林恩","左左","倒吊天使","艾雯爵士"],"brief":"噩节点把城镇封入梦境展示多条可交换命运路径，把灵聚集为灭世黑炎燃料，林恩彻底斩断妥协退路，孤身杀入被舍弃的时间支流屠戮七十一柱魇魔投影，全面打响时间战争。"},"E770":{"name":"未来的不确定性与过去的重合","stage":"S98","location":"废弃时间支流、圣堂大门外、残存黑夜城","chars":["林恩","左左","倒吊天使","艾维儿"],"brief":"未来影像开始提前落入过去，林恩与左左在同一节点见多个自己，敌方投下一段失败未来试图让林恩相信道路俱毁，林恩与过去的自我轨迹完成宿命重合，即将把三柱魇魔拖入时间裂隙审问。"},"E771":{"name":"时间之外的黑影","stage":"S98","location":"两百多年前深渊红月战场、时间裂隙、时间之外","chars":["林恩","左左","倒吊天使","渡鸦","紫罗兰大君"],"brief":"空白区域凝成一根没有颜色的柱状实体，黑火靠近即被压低、空间法则无法锁定，实体沿历史追杀过去渡鸦，把时间长河切出空白。"},"E772":{"name":"时间战争与空白之柱","stage":"S99","location":"两百多年前通往天国战争废墟的夹缝空间","chars":["林恩","渡鸦","未来画家"],"brief":"七十二柱的黑影覆历史战场，画家残影于另一侧维持回当前的法则线，空白柱实体自噩中独立，向过去渡鸦射出无色弹体。"},"E773":{"name":"空白一击与画家阻挡","stage":"S99","location":"两百多年前通往天国战争废墟的夹缝空间","chars":["林恩","渡鸦","未来画家","时间王","紫罗兰大君"],"brief":"无色弹体沿过去渡鸦因果直接抵达，画家残影在最后瞬间横置拦截、被弹贯穿仍把攻击偏离渡鸦核心，过去人类林恩的跃迁节点化险为夷，林恩明确了完整时间神格与时间神王的存在。"},"E774":{"name":"蝴蝶效应与自己的过去","stage":"S99","location":"历史长河各处节点","chars":["林恩","左左","血锯","人偶夫人","渡鸦"],"brief":"同一时间点浮现多个不同推演的林恩身影，林恩亲身体会到蝴蝶效应的致命凶险，并由此切入一万至十万年前“大坠落”与旧日之神战争的远古秘史。"},"E775":{"name":"旧日之神与遥远过去","stage":"S99","location":"远古地狱","chars":["林恩","左左","渡鸦"],"brief":"时间长河退去表层，旧神神国与大坠落遗址显现，林恩见远古渡鸦与大坠落的真实顺序，确认其力量经过失败与重铸方成今日之路。"},"E776":{"name":"新世界的记忆","stage":"S99","location":"远古地狱上空、远古渡鸦的灵魂记忆深处","chars":["林恩","渡鸦","未来画家","紫罗兰大君","奈奈子"],"brief":"渡鸦自新世界法则工厂被制造，按紫罗兰帝国命令执行清扫，第一位真理神诞生于高压秩序，被帝国视为错误，林恩看清了新世界秩序异化的历史脉络。"},"E777":{"name":"这个世界没有真理","stage":"S99","location":"远古渡鸦记忆深处","chars":["林恩","渡鸦","未来画家","紫罗兰大君"],"brief":"真理神之死被帝国写成『世界没有真理』，永恒寒冬下渡鸦群体被重复编排、个人记忆被抹去，林恩彻底明白了为何这只远古渡鸦会走上背叛帝国、统领旧日之神的道路。"},"E778":{"name":"他一定会死","stage":"S99","location":"远古地狱监牢、远古地狱海面上空","chars":["林恩","左左","渡鸦","未来画家","紫罗兰大君"],"brief":"空白实体确认远古渡鸦必须死亡，林恩以有限黑火只能让实体偏离目标、不能伤其本体，林恩为护住历史因果与第七十二柱黑袍身影正面交锋。"},"E779":{"name":"不寒而栗的计划","stage":"S99","location":"远古地狱、渡鸦山峰、旧日之神战争爆发当日的地狱天空","chars":["林恩","渡鸦","未来画家"],"brief":"林恩自渡鸦灵魂共享进入旧根系，见群体以同一因果线承载记忆并可集中成一次穿透历史的自爆，画家残影于共享边缘渐失秩序。"},"E780":{"name":"历史更迭与注定宿命","stage":"S99","location":"远古地狱大峡谷","chars":["林恩","渡鸦","血肉支配者"],"brief":"七十二噩自时间外压入根系核心，远古渡鸦聚同伴灵魂备好自爆，跨越数万年的历史因果闭环在此刻彻底锁死，林恩不得不作为那道“白发身影”向过去的自己挥剑。"},"E781":{"name":"如果我必须杀了你","stage":"S99","location":"地狱裂谷、旧神反抗战场、时间之外的黄金梦境","chars":["林恩","渡鸦","未来画家"],"brief":"林恩确认自爆可行性正是因自己降临扩大活着的渡鸦与共享灵魂数量，古老渡鸦与历代渡鸦灵魂被收入黄金梦境，历史重回正轨，游魂巷新生渡鸦的闭环得以确立。"},"E782":{"name":"需要被斩掉的因果","stage":"S99","location":"岁月长河末端、时间终末战场、黑夜城现实本体","chars":["林恩","左左","渡鸦","入梦者","时间王"],"brief":"林恩左左抵时间终点，七十一噩与空白实体同现，林恩以完整黑火先清大部分噩再压火于实体，遭反击退回当前，林恩确认自身黑火与终焉同路，洞察时间神王在时间终末的威胁。"},"E783":{"name":"与时间赛跑","stage":"S100","location":"黑夜城、时间终末战场、新世界早期天堂之战边境","chars":["林恩","左左","入梦者","紫罗兰大君"],"brief":"林恩不以一次性抹除历史为方案，回到早期天堂战争沿织梦与灵能的轨迹寻找能够解释终焉的节点，林恩确立以时间权柄记载过去的破局方向，并在天堂之战初期成功接触尚未认识自己的织梦。"},"E784":{"name":"再相逢与等你一千年","stage":"S100","location":"初创星球篝火旁、横跨新旧世界的极北雪原、凡尘人世","chars":["林恩","左左","入梦者"],"brief":"林恩向织梦展示黑火与未来战争记忆，她拒绝把眼前林恩当未来答案，织梦在冬泉谷风雪守候中本源渐复，虽嘴硬抗拒，却已被带入凡尘俗世迎向心灵蜕变。"},"E785":{"name":"你我皆凡人与偿还眼泪","stage":"S100","location":"凡尘俗世、冬泉谷木屋与风雪洞窟、历代先贤灵能洪流","chars":["林恩","入梦者"],"brief":"林恩把织梦带入凡人城市梦境见战争、饥饿、互救与守护陌生孩子，织梦真正蜕变为懂得珍惜众生的盟友，冬泉谷千年因果圆满，林恩踏入三位一体之主的远古回响。"},"E786":{"name":"三位一体之主","stage":"S100","location":"历代先贤灵能洪流、大世余烬起点、旧世永恒回声","chars":["林恩","入梦者"],"brief":"林恩确认守护众生的黑火与终焉灾厄同出一源，旧世「永恒」与「终焉」的二元对立真相浮出水面，三位一体之主跨越时空注视、「祂就是我啊」同源揭秘、旧世永恒乌托邦与黑火诞生历史成立。"},"E787":{"name":"苦痛轮回与梦境真相","stage":"S100","location":"亘古灵能最深层、苦痛轮回核心、冬泉谷苏醒点","chars":["林恩"],"brief":"远古记忆展开：三位一体之主即梦主，它燃永恒把自身分裂成永恒与终焉、入终焉内部控轮回中段，把宇宙做成可反复运行的梦。"},"E788":{"name":"最后的告别与过去杀招","stage":"S100","location":"冬泉谷漫天风雪、岁月长河、当前现实黑夜城","chars":["林恩","左左","渡鸦","入梦者"],"brief":"林恩回冬泉谷向完成恢复的织梦告别、把许诺的眼泪留在谷中随后返回当前，冬泉谷千年篇章温情收束，而贯穿整条时间线的渡鸦载体悖论危机全面爆发，逼迫林恩逆流赶赴最后的时间战争。"},"E789":{"name":"最后的时间战争与截杀","stage":"S100","location":"岁月长河上游、新世界最初的极北雪原与无序深空","chars":["林恩","渡鸦","未来画家","奈奈子"],"brief":"空白实体摊牌——真正的杀招不是灵魂变重而是林恩反复降临造出的悖论，它试图以一只仍存活渡鸦之死把悖论同时反压林恩。"},"E790":{"name":"你到底是谁与唯一活下来的希望","stage":"S100","location":"紫罗兰世界冬泉谷法师塔外、岁月长河、时间终末孤塔","chars":["林恩","渡鸦","未来画家","紫罗兰大君","奈奈子"],"brief":"画家看见最后载体喊出奈奈子之名，旧日关系与空白实体形态重叠，林恩确认空白实体与紫罗兰大君、灾厄相连，第七十二柱黑衣人影的真身与骨鸦悖论杀局彻底揭晓。"},"E791":{"name":"时代终末的接轨","stage":"S100","location":"岁月长河接轨区、现实黑夜城外虚空、时间终末孤岛前缘","chars":["林恩","左左","紫罗兰大君"],"brief":"林恩入未来尽头，过去现在未来如多层透明薄片互相覆盖，时间权柄自合流中心显现，却要先过一座由悖论组成的空门。"},"E792":{"name":"终焉倒计时与轮回","stage":"S100","location":"时代接轨中心、时间终末孤岛幻境、终焉倒计时苍穹","chars":["林恩","左左","轮回神王","时间王","紫罗兰大君"],"brief":"时间王承认是梦主最早的伙伴之一、曾背叛轮回结构，无解的时代接轨死局被轮回神王强行撕开生路，时间神王与轮回跨越万古的兄弟宿命浮出水面。"},"E793":{"name":"这是我最后能帮你的","stage":"S100","location":"时间之外挡劫战场、林恩深层记忆走马灯、轮回锁链锚点","chars":["林恩","左左","轮回神王","时间王","紫罗兰大君"],"brief":"林恩跨越濒死劫难重获新生，轮回神王以自身为囚笼替他锁住过去的因果崩坏，为他争取到前往时间终末决战的最后窗口。"},"E794":{"name":"最终的决战","stage":"S101","location":"时间长河轮回锚点、通往时间终末的尽头之路","chars":["林恩","左左","轮回神王","时间王","紫罗兰大君"],"brief":"林恩循轮回碎片与梦主记忆进入终焉核心，七十一噩沿城展阵、时间王在城门前再邀其加入终焉，林恩彻底融合轮回神王的万世经验与心性。"},"E795":{"name":"大结局与原初身体","stage":"S101","location":"终焉之城、紫罗兰大君残破王庭、时间长河战场","chars":["林恩","渡鸦","轮回神王","时间王","紫罗兰大君"],"brief":"林恩以稳定黑火逐一