  function cleanChatMessageText(rawMes, isUser) {
    let text = String(rawMes || '');
    if (isUser) {
      const userBlockMatch = text.match(/<本轮用户输入>\s*([\s\S]*?)\s*<\/本轮用户输入>/i);
      if (userBlockMatch) text = userBlockMatch[1];
    }
    text = text
      .replace(/<GypDSL>[\s\S]*?<\/GypDSL>/gi, '')
      .replace(/<tableEdit>[\s\S]*?<\/tableEdit>/gi, '')
      .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
      .replace(/<thought>[\s\S]*?<\/thought>/gi, '')
      .replace(/<recall>[\s\S]*?<\/recall>/gi, '')
      .replace(/<supplement>[\s\S]*?<\/supplement>/gi, '')
      .replace(/<记忆回溯>[\s\S]*?<\/记忆回溯>/gi, '')
      .replace(/<已发生的事件概览>[\s\S]*?<\/已发生的事件概览>/gi, '')
      .replace(/<!--[\s\S]*?-->/g, '')
      .trim();
    return text;
  }

  const GypStateAgent = {
    getConfig: function () { return agentConfig; },
    saveConfig: saveAgentConfig,
    buildContextPacket: function () {
      let charDesc = '林恩（玩家主权独占角色），死界亡者之镇血锯药剂店学徒，左手寄生王后神魂左左。';
      let chatHistoryText = '';
      let latestFloorText = '';
      const count = clampNum(agentConfig.historyCount, 1, 100, 20);
      try {
        const w = window.top || window.parent || window;
        if (w.SillyTavern && typeof w.SillyTavern.getContext === 'function') {
          const ctx = w.SillyTavern.getContext();
          if (ctx) {
            if (ctx.characters && ctx.characterId !== undefined && ctx.characters[ctx.characterId]) {
              const ch = ctx.characters[ctx.characterId];
              charDesc = (ch.description || '') + '\n' + (ch.personality || '') + '\n' + (ch.scenario || '');
            }
            if (Array.isArray(ctx.chat) && ctx.chat.length) {
              const slice = ctx.chat.slice(-count);
              chatHistoryText = slice.map(function (m, idx) {
                const speaker = m.is_user ? '【玩家/林恩】' : ('【' + (m.name || '叙事AI') + '】');
                const cleanMes = cleanChatMessageText(m.mes, Boolean(m.is_user));
                return '#' + (idx + 1) + ' ' + speaker + '：\n' + cleanMes;
              }).join('\n\n');
              const lastMsg = slice[slice.length - 1];
              latestFloorText = lastMsg ? cleanChatMessageText(lastMsg.mes, Boolean(lastMsg.is_user)) : '';
            }
          }
        }
      } catch (_) {}
      const mainEvtId = currentState.世界.当前主事件 || 'E01';
      const evtLore = (GYP_LORE_DB.events && GYP_LORE_DB.events[mainEvtId]) || {};
      const stageId = currentState.世界.阶段编号 || 'S0';
      const stageLore = (GYP_LORE_DB.stages && GYP_LORE_DB.stages[stageId]) || {};
      const snapshot = {
        世界: currentState.世界,
        林恩: currentState.林恩,
        事件: {
          当前主事件: currentState.事件.当前主事件,
          唯一活跃事件: currentState.事件.唯一活跃事件,
          近期预兆: currentState.事件.近期预兆
        },
        在场与已解锁角色: Object.values(currentState.关系).filter(function (c) { return c.present || c.unlocked; }).map(function (c) {
          return {
            姓名: c.name, 在场: c.present, 好感: c.好感, 信赖: c.信赖, 吸引: c.吸引, 戒备: c.戒备,
            恶堕: c.恶堕, 涩涩度: c.涩涩度, 关系创伤: c.关系创伤,
            情感开发度: c.情感开发度, 驯服度: c.驯服度, 崩坏值: c.崩坏值, 恨意值: c.恨意值,
            位置: c.位置, 人物阶段: c.人物阶段, 最近互动: c.最近互动
          };
        }),
        系统: {
          当前任务: currentState.系统.当前任务,
          任务阶段: currentState.系统.任务阶段,
          任务状态: currentState.系统.任务状态,
          沙盒: currentState.系统.沙盒,
          当前动态模块IDs: Object.keys(currentState.系统.动态模块 || {})
        }
      };
      const userPrompt = [
        '=== 一、当前阶段与世界书锚点背景 ===',
        '当前阶段：' + stageId + ' ' + (stageLore.title || currentState.世界.阶段名称) + '（' + (stageLore.summary || '') + '）',
        '当前主事件锚点：' + mainEvtId + ' ' + (evtLore.name || '') + ' — ' + (evtLore.brief || ''),
        '角色卡核心设定摘要：' + charDesc.slice(0, 1200),
        '',
        '=== 二、当前状态栏快照 (stat_data) ===',
        JSON.stringify(snapshot, null, 2),
        '',
        '=== 三、最近上下文对话记录（最近 ' + count + ' 层） ===',
        chatHistoryText || '（当前为独立预览环境或尚无历史聊天记录，请根据当前状态快照与最新情境生成状态更新与专属 @module 动态模块）',
        '',
        '=== 四、最新一轮正文楼层 ===',
        latestFloorText || '（请基于当前主事件 ' + mainEvtId + ' 与在场角色状态，输出 <GypDSL> 更新指令及 1~2 个切合当前剧情的 @module 动态场景模块）',
        '',
        '请立即仅输出 <GypDSL>...</GypDSL> 代码块：'
      ].join('\n');
      return {
        systemPrompt: GYP_STATE_OFFICER_SYSTEM_PROMPT,
        userPrompt: userPrompt
      };
