    fetchModels: async function () {
      const base = String(agentConfig.apiUrl || '').replace(/\/+$/, '');
      if (!base) throw new Error('请先填写 API Base URL');
      const headers = { 'Content-Type': 'application/json' };
      if (agentConfig.apiKey) headers['Authorization'] = 'Bearer ' + agentConfig.apiKey.trim();
      const resp = await fetch(base + '/models', { method: 'GET', headers: headers });
      if (!resp.ok) throw new Error('HTTP ' + resp.status + ' ' + resp.statusText);
      const data = await resp.json();
      const list = Array.isArray(data && data.data) ? data.data.map(function (m) { return m.id; }).filter(Boolean) : [];
      agentRuntime.models = list;
      return list;
    },
    testConnection: async function () {
      const base = String(agentConfig.apiUrl || '').replace(/\/+$/, '');
      if (!base || !agentConfig.apiKey) throw new Error('请先填写 API Base URL 和 API Key');
      const t0 = Date.now();
      const resp = await fetch(base + '/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + agentConfig.apiKey.trim()
        },
        body: JSON.stringify({
          model: agentConfig.model || 'gpt-4o-mini',
          messages: [{ role: 'user', content: '请仅回复：<GypDSL># 连接正常</GypDSL>' }],
          max_tokens: 64,
          temperature: 0.1
        })
      });
      if (!resp.ok) {
        const errTxt = await resp.text();
        throw new Error('HTTP ' + resp.status + ': ' + errTxt.slice(0, 180));
      }
      const data = await resp.json();
      const reply = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
      return { latencyMs: Date.now() - t0, reply: reply.trim() };
    },
    runAgentUpdate: async function () {
      if (agentRuntime.busy) return;
      const base = String(agentConfig.apiUrl || '').replace(/\/+$/, '');
      if (!base || !agentConfig.apiKey) {
        agentRuntime.lastLog = '❌ 未配置 API Base URL 或 API Key，无法发起远程二连发请求。你仍可在右侧直接编写或载入示例 <GypDSL> 立即编译生效！';
        renderAgentConsoleModal();
        return;
      }
      agentRuntime.busy = true;
      agentRuntime.lastLog = '🟡 正在组装全量上下文并请求专职状态官 AI (' + escHtml(agentConfig.model) + ') ...';
      updateAgentStatusIndicators();
      renderAgentConsoleModal();
      try {
        const pkt = this.buildContextPacket();
        const t0 = Date.now();
        const resp = await fetch(base + '/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + agentConfig.apiKey.trim()
          },
          body: JSON.stringify({
            model: agentConfig.model || 'gpt-4o-mini',
            messages: [
              { role: 'system', content: pkt.systemPrompt },
              { role: 'user', content: pkt.userPrompt }
            ],
            temperature: clampNum(agentConfig.temperature, 0, 2, 0.2),
            max_tokens: clampNum(agentConfig.maxTokens, 128, 8192, 2048)
          })
        });
        if (!resp.ok) {
          const errText = await resp.text();
          throw new Error('HTTP ' + resp.status + ': ' + errText.slice(0, 200));
        }
        const data = await resp.json();
        const content = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
        const res = GypDslCompiler.compileAndApply(content);
        agentRuntime.lastLog = '🟢 专职状态官推演完成（耗时 ' + (Date.now() - t0) + 'ms）：\n' + (res.logs.join('\n') || '已同步状态栏。');
      } catch (err) {
        agentRuntime.lastLog = '❌ 专职状态官请求异常：' + (err && err.message ? err.message : String(err));
      } finally {
        agentRuntime.busy = false;
        updateAgentStatusIndicators();
        renderAgentConsoleModal();
      }
    }
  };

  function ensureAgentConsoleModal() {
    const hostDoc = getHostDocument();
    ensurePortalRoot();
    let el = hostDoc.getElementById(AGENT_CONSOLE_ID);
    if (el && el.__gypOwnerWindow !== window) {
      el.remove();
      el = null;
    }
    if (!el) {
      el = hostDoc.createElement('div');
      el.id = AGENT_CONSOLE_ID;
      el.__gypOwnerWindow = window;
      hostDoc.body.appendChild(el);
      el.addEventListener('click', function (ev) {
        if (ev.target === el) closeAgentConsoleModal();
      });
      bindAgentConsoleEvents(el);
    }
    return el;
  }

