              <div>• 新角色自动建档：<code>@char[任意新NPC名] 解锁=true 在场=true 好感=65 阶段="初识" 互动="..."</code></div>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  function readFormIntoConfig(rootEl) {
    const getVal = function (id) {
      const el = rootEl.querySelector('#' + id);
      return el ? el.value : '';
    };
    const autoEl = rootEl.querySelector('#gyp-cfg-autotrigger');
    saveAgentConfig({
      apiUrl: getVal('gyp-cfg-url').trim() || 'https://api.openai.com/v1',
      apiKey: getVal('gyp-cfg-key').trim(),
      model: getVal('gyp-cfg-model').trim() || 'gpt-4o-mini',
      temperature: clampNum(getVal('gyp-cfg-temp'), 0, 2, 0.2),
      maxTokens: clampNum(getVal('gyp-cfg-tokens'), 128, 8192, 2048),
      historyCount: clampNum(getVal('gyp-cfg-history'), 1, 100, 20),
      autoTrigger: Boolean(autoEl && autoEl.checked)
    });
  }

  function bindAgentConsoleEvents(el) {
    if (el.__gypConsoleBound) return;
    el.__gypConsoleBound = true;
    el.addEventListener('click', async function (ev) {
      if (ev.target.closest('#gyp-console-close-btn')) {
        closeAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-cfg-toggle-key')) {
        readFormIntoConfig(el);
        agentRuntime.showKey = !agentRuntime.showKey;
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-cfg-save-btn')) {
        readFormIntoConfig(el);
        agentRuntime.lastLog = '💾 配置已保存至本地浏览器 (localStorage)。当前状态：' + getAgentStatusInfo().text;
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-cfg-fetch-models')) {
        readFormIntoConfig(el);
        agentRuntime.lastLog = '🔄 正在从 ' + agentConfig.apiUrl + '/models 拉取可用模型列表...';
        renderAgentConsoleModal();
        try {
          const list = await GypStateAgent.fetchModels();
          agentRuntime.lastLog = '🟢 成功拉取 ' + list.length + ' 个模型！可从下拉框直接选择。';
        } catch (err) {
          agentRuntime.lastLog = '❌ 拉取模型失败：' + (err && err.message ? err.message : String(err));
        }
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-cfg-test-btn')) {
        readFormIntoConfig(el);
        agentRuntime.lastLog = '⚡ 正在测试 API 连接 (' + agentConfig.model + ') ...';
        renderAgentConsoleModal();
        try {
          const res = await GypStateAgent.testConnection();
          agentRuntime.lastLog = '🟢 API 连接测试成功！延迟：' + res.latencyMs + 'ms\n模型响应：' + res.reply;
        } catch (err) {
          agentRuntime.lastLog = '❌ API 连接测试失败：' + (err && err.message ? err.message : String(err));
        }
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-cfg-run-now-btn')) {
        readFormIntoConfig(el);
        await GypStateAgent.runAgentUpdate();
        return;
      }
      if (ev.target.closest('#gyp-cfg-preview-prompt-btn')) {
        readFormIntoConfig(el);
        agentRuntime.showPromptPreview = !agentRuntime.showPromptPreview;
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-dsl-apply-btn')) {
        const ta = el.querySelector('#gyp-dsl-editor-textarea');
        const rawDsl = ta ? ta.value : '';
        const res = GypDslCompiler.compileAndApply(rawDsl);
        agentRuntime.lastLog = '🟢 GYP-DSL 编译并应用成功！\n' + (res.logs.join('\n') || '无变更项');
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-dsl-cycle-sample-btn')) {
        agentRuntime.sampleIndex = (agentRuntime.sampleIndex + 1) % SAMPLE_DSL_TEMPLATES.length;
        const sample = SAMPLE_DSL_TEMPLATES[agentRuntime.sampleIndex];
        const res = GypDslCompiler.compileAndApply(sample.dsl);
        agentRuntime.lastLog = '🎲 已载入并编译预设模板【' + sample.name + '】：\n' + res.logs.join('\n');
        renderAgentConsoleModal();
        return;
      }
      if (ev.target.closest('#gyp-dsl-clear-mods-btn')) {
        const res = GypDslCompiler.compileAndApply('<GypDSL>\n@clear_modules\n</GypDSL>');
        agentRuntime.lastLog = '🗑️ ' + res.logs.join('\n');
        renderAgentConsoleModal();
        return;
      }
    });
    el.addEventListener('change', function (ev) {
      if (ev.target && ev.target.id === 'gyp-cfg-model-select' && ev.target.value) {
        const modelInput = el.querySelector('#gyp-cfg-model');
        if (modelInput) modelInput.value = ev.target.value;
        readFormIntoConfig(el);
      }
    });
  }

  function openAgentConsoleModal() {
    currentState = normalizeState(resolveLiveState());
    const el = ensureAgentConsoleModal();
    renderAgentConsoleModal();
    el.classList.add('is-open');
  }

  function closeAgentConsoleModal() {
    const hostDoc = getHostDocument();
    const el = hostDoc.getElementById(AGENT_CONSOLE_ID);
    if (el) el.classList.remove('is-open');
  }

  function renderActivePortalView() {
    const hostDoc = getHostDocument();
    const rootEl = hostDoc.getElementById(PORTAL_ROOT_ID);
    if (!rootEl) return;
    const subEl = rootEl.querySelector('#gyp-modal-subtitle');
    if (subEl) {
      const w = currentState.世界;
      subEl.textContent = w.阶段编号 + ' · ' + w.阶段名称 + ' · 当前锚点 ' + w.当前主事件 + ' ｜ ' + w.当前世界 + '·' + w.当前地点 + ' ｜ 玩家主权绝对独占';
    }
    const modCountBadge = rootEl.querySelector('#gyp-modal-mod-count-badge');
    if (modCountBadge) {
      const cnt = getActiveModulesFor('modal').length;
      modCountBadge.textContent = '⚡ 动态模块 ×' + cnt;
    }
    const visBtns = rootEl.querySelectorAll('#gyp-modal-vis-nav [data-set-hide-unreached]');
    visBtns.forEach(function (btn) {
      const wantHide = btn.getAttribute('data-set-hide-unreached') === '1';
      btn.classList.toggle('is-active', wantHide === Boolean(uiState.hideUnreached));
    });
    updateAgentStatusIndicators();
    const tabBtns = rootEl.querySelectorAll('[data-tab-view]');
    tabBtns.forEach(function (btn) {
      const v = Number(btn.getAttribute('data-tab-view'));
      btn.classList.toggle('is-active', v === uiState.activeView);
    });
    const bodyEl = rootEl.querySelector('#gyp-modal-body');
    if (!bodyEl) return;
    if (uiState.activeView === 1) bodyEl.innerHTML = renderView1();
    else if (uiState.activeView === 2) bodyEl.innerHTML = renderView2();
    else if (uiState.activeView === 3) bodyEl.innerHTML = renderView3();
    else if (uiState.activeView === 4) bodyEl.innerHTML = renderView4();
  }
  function bindPortalEvents(rootEl) {
    if (rootEl.__gypBound) return;
    rootEl.__gypBound = true;
    rootEl.addEventListener('click', function (ev) {
      const closeBtn = ev.target.closest('#gyp-modal-close-btn');
      if (closeBtn) {
        closeGrimoirePortal();
        return;
      }
      if (ev.target.closest('#gyp-modal-agent-btn') || ev.target.closest('[data-open-agent-console]')) {
        openAgentConsoleModal();
        return;
      }
      const setHideBtn = ev.target.closest('[data-set-hide-unreached]');
      if (setHideBtn) {
        setHideUnreached(setHideBtn.getAttribute('data-set-hide-unreached') === '1');
        renderCompactStrip();
        renderActivePortalView();
        return;
      }
      if (ev.target.closest('[data-toggle-hide-unreached]')) {
        setHideUnreached(!uiState.hideUnreached);
        renderCompactStrip();
        renderActivePortalView();
        return;
      }
      const tabBtn = ev.target.closest('[data-tab-view]');
      if (tabBtn) {
        uiState.activeView = Number(tabBtn.getAttribute('data-tab-view')) || 1;
        renderActivePortalView();
        return;
      }
      const charFilterBtn = ev.target.closest('[data-char-filter]');
      if (charFilterBtn) {
        uiState.charFilter = charFilterBtn.getAttribute('data-char-filter') || 'all';
        renderActivePortalView();
        return;
      }
      const selectCharCard = ev.target.closest('[data-select-char]');
      if (selectCharCard) {
        uiState.selectedChar = selectCharCard.getAttribute('data-select-char') || '血锯';
        renderActivePortalView();
        return;
      }
      const codexCatBtn = ev.target.closest('[data-codex-cat]');
      if (codexCatBtn) {
        uiState.codexCategory = codexCatBtn.getAttribute('data-codex-cat') || '全部';
        renderActivePortalView();
        return;
      }
      if (ev.target.closest('[data-toggle-codex-all]')) {
        uiState.codexShowAll = !uiState.codexShowAll;
        renderActivePortalView();
        return;
      }
      if (ev.target.closest('[data-toggle-timeline-all]')) {
        uiState.timelineShowAll = !uiState.timelineShowAll;
        renderActivePortalView();
        return;
      }
      if (ev.target.closest('[data-toggle-stages-panel]')) {
        uiState.showStagesGrid = !uiState.showStagesGrid;
        renderActivePortalView();
        return;
      }
      const eraFilterBtn = ev.target.closest('[data-era-filter]');
      if (eraFilterBtn) {
        uiState.timelineEra = eraFilterBtn.getAttribute('data-era-filter') || '全部';
        renderActivePortalView();
        return;
      }
    });
    rootEl.addEventListener('input', function (ev) {
      if (ev.target && ev.target.id === 'gyp-char-search-input') {
        uiState.charSearch = ev.target.value || '';
        const pos = ev.target.selectionStart;
        renderActivePortalView();
        const nextInput = rootEl.querySelector('#gyp-char-search-input');
        if (nextInput) {
          nextInput.focus();
          try { nextInput.setSelectionRange(pos, pos); } catch (_) {}
        }
      } else if (ev.target && ev.target.id === 'gyp-codex-search-input') {
        uiState.codexSearch = ev.target.value || '';
        const pos = ev.target.selectionStart;
        renderActivePortalView();
        const nextInput = rootEl.querySelector('#gyp-codex-search-input');
        if (nextInput) {
          nextInput.focus();
          try { nextInput.setSelectionRange(pos, pos); } catch (_) {}
        }
      } else if (ev.target && ev.target.id === 'gyp-timeline-search-input') {
        uiState.timelineSearch = ev.target.value || '';
        const pos = ev.target.selectionStart;
        renderActivePortalView();
        const nextInput = rootEl.querySelector('#gyp-timeline-search-input');
        if (nextInput) {
          nextInput.focus();
          try { nextInput.setSelectionRange(pos, pos); } catch (_) {}
        }
      }
    });
  }
  function openGrimoirePortal(viewNum, charName) {
    currentState = normalizeState(resolveLiveState());
    renderCompactStrip();
    if (viewNum) uiState.activeView = Number(viewNum) || 1;
    if (charName) {
      uiState.activeView = 2;
      uiState.selectedChar = charName;
      if (currentState.关系[charName] && !currentState.关系[charName].present) {
        uiState.charFilter = currentState.关系[charName].unlocked ? 'unlocked' : 'all';
      }
    }
    const rootEl = ensurePortalRoot();
    renderActivePortalView();
    rootEl.classList.add('is-open');
  }
  function closeGrimoirePortal() {
    const hostDoc = getHostDocument();
    const rootEl = hostDoc.getElementById(PORTAL_ROOT_ID);
    if (rootEl) rootEl.classList.remove('is-open');
  }
  function bindStripEvents() {
    const stripRoot = document.getElementById('gyp-strip-root');
    if (!stripRoot || stripRoot.__gypStripBound) return;
    stripRoot.__gypStripBound = true;
    stripRoot.addEventListener('click', function (ev) {
      const mainBtn = ev.target.closest('#gyp-open-grimoire-main');
      if (mainBtn) {
        openGrimoirePortal(uiState.activeView || 1);
        return;
      }
      if (ev.target.closest('[data-toggle-hide-unreached]')) {
        setHideUnreached(!uiState.hideUnreached);
        renderCompactStrip();
        const hostDoc = getHostDocument();
        const rootEl = hostDoc.getElementById(PORTAL_ROOT_ID);
        if (rootEl && rootEl.classList.contains('is-open')) {
          renderActivePortalView();
        }
        return;
      }
      if (ev.target.closest('#gyp-open-agent-btn')) {
        openAgentConsoleModal();
        return;
      }
      if (ev.target.closest('[data-toggle-strip-mods]')) {
        uiState.stripModulesCollapsed = !uiState.stripModulesCollapsed;
        renderCompactStrip();
        return;
      }
      const viewBtn = ev.target.closest('[data-open-view]');
      if (viewBtn) {
        const v = Number(viewBtn.getAttribute('data-open-view')) || 1;
        openGrimoirePortal(v);
        return;
      }
      const charJump = ev.target.closest('[data-char-jump]');
      if (charJump) {
        const cname = charJump.getAttribute('data-char-jump');
        openGrimoirePortal(2, cname);
        return;
      }
    });
  }
  function refreshAll() {
    currentState = normalizeState(resolveLiveState());
    renderCompactStrip();
    updateAgentStatusIndicators();
    const hostDoc = getHostDocument();
    const rootEl = hostDoc.getElementById(PORTAL_ROOT_ID);
    if (rootEl && rootEl.classList.contains('is-open')) {
      renderActivePortalView();
    }
  }
  bindStripEvents();
  refreshAll();
  try {
    const exposeTargets = [window];
    if (window.top && window.top !== window) exposeTargets.push(window.top);
    exposeTargets.forEach(function (w) {
      w.GypDslCompiler = GypDslCompiler;
      w.GypStateAgent = GypStateAgent;
      w.openGypGrimoire = openGrimoirePortal;
      w.openGypAgentConsole = openAgentConsoleModal;
      w.refreshGypStatus = refreshAll;
    });
  } catch (_) {}
  try {
    if (typeof eventOn === 'function') {
      eventOn('mag_variable_updated', refreshAll);
      eventOn('mvu_variable_updated', refreshAll);
      const topWin = (function () {
        try { return window.top || window.parent || window; } catch (_) { return window; }
      })();
      if (!topWin.__GYP_STATE_AGENT_STATE__) {
        topWin.__GYP_STATE_AGENT_STATE__ = { running: false, lastHash: '' };
      }
      const onGenEnded = function () {
        if (!agentConfig.autoTrigger || !agentConfig.apiKey || agentRuntime.busy) return;
        try {
          const ctx = topWin.SillyTavern && typeof topWin.SillyTavern.getContext === 'function'
            ? topWin.SillyTavern.getContext()
            : null;
          if (typeof window.getCurrentMessageId === 'function' && ctx && Array.isArray(ctx.chat) && ctx.chat.length) {
            const myMsgId = window.getCurrentMessageId();
            if (typeof myMsgId === 'number' && myMsgId >= 0 && myMsgId !== ctx.chat.length - 1) return;
          }
          if (ctx && Array.isArray(ctx.chat) && ctx.chat.length) {
            const lastMsg = ctx.chat[ctx.chat.length - 1];
            if (!lastMsg || lastMsg.is_user) return;
            const msgHash = String(ctx.chat.length) + ':' + String((lastMsg.mes || '').length);
            if (topWin.__GYP_STATE_AGENT_STATE__.running || topWin.__GYP_STATE_AGENT_STATE__.lastHash === msgHash) return;
            topWin.__GYP_STATE_AGENT_STATE__.running = true;
            topWin.__GYP_STATE_AGENT_STATE__.lastHash = msgHash;
          } else {
            if (topWin.__GYP_STATE_AGENT_STATE__.running) return;
            topWin.__GYP_STATE_AGENT_STATE__.running = true;
          }
        } catch (_) {}
        setTimeout(function () {
          Promise.resolve(GypStateAgent.runAgentUpdate()).finally(function () {
            try { topWin.__GYP_STATE_AGENT_STATE__.running = false; } catch (_) {}
          });
        }, 350);
      };
      const evRendered = (typeof tavern_events !== 'undefined' && tavern_events.CHARACTER_MESSAGE_RENDERED)
        ? tavern_events.CHARACTER_MESSAGE_RENDERED
        : 'character_message_rendered';
      const evGenEnded = (typeof tavern_events !== 'undefined' && tavern_events.GENERATION_ENDED)
        ? tavern_events.GENERATION_ENDED
        : 'generation_ended';
      eventOn(evRendered, onGenEnded);
      eventOn(evGenEnded, onGenEnded);
    }
  } catch (_) {}
})();
