async function importFirstAvailable(urls) {
  let lastError;
  for (const url of urls) {
    try {
      await import(url);
      return;
    } catch (error) {
      lastError = error;
      console.warn(`[诡异药剂师v0.23] MVU 加载失败，尝试备用源：${url}`, error);
    }
  }
  throw lastError ?? new Error('没有可用的 MVU 运行源');
}

